import type { TodoGateway, TodoRecord } from '../application/TodoGateway'

export class HttpTodoGateway implements TodoGateway {
  private readonly baseUrl: string

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl
  }

  async list(signal?: AbortSignal): Promise<TodoRecord[]> {
    const response = await fetch(`${this.baseUrl}/api/todos`, { signal })
    if (!response.ok) throw new Error(`GET /api/todos answered ${response.status}`)
    return (await response.json()) as TodoRecord[]
  }
}
import type { TodoViewModel } from '../../application/TodoViewModel'

type TodoItemProps = {
  todo: TodoViewModel
}

export const TodoItem = ({ todo }: TodoItemProps) => (
  <li>
    {todo.title}
    {todo.status === 'done' ? ' (done)' : null}
  </li>
)
import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import { TodoItem } from '../TodoItem/TodoItem'
import { useTodos } from '../useTodos/useTodos'

export const TodoList = () => {
  const state = useTodos()

  if (state.status === 'loading') return <p>Loading todos…</p>
  if (state.status === 'failed') return <ErrorMessage>The todos could not be loaded.</ErrorMessage>

  return state.todos.length > 0 ? (
    <ul aria-label="Todos">
      {state.todos.map((todo) => (
        <TodoItem key={todo.id} todo={todo} />
      ))}
    </ul>
  ) : (
    <p>No todos yet.</p>
  )
}
