import { useState } from 'react'

import type { TodoViewModel } from '../../application/TodoViewModel'
import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

type TodoItemProps = {
  todo: TodoViewModel
}

type CompletionState = 'idle' | 'pending' | 'completed' | 'already-completed' | 'failed'

export const TodoItem = ({ todo }: TodoItemProps) => {
  const { completeTodo } = useTodosUseCases()
  const [completion, setCompletion] = useState<CompletionState>('idle')

  const complete = () => {
    setCompletion('pending')
    completeTodo.execute(todo.id).then(setCompletion, () => setCompletion('failed'))
  }

  const done = todo.status === 'done' || completion === 'completed'

  return (
    <li>
      {todo.title}
      {done ? ' (done)' : null}{' '}
      <button type="button" onClick={complete} disabled={completion === 'pending'}>
        Complete
      </button>
      {completion === 'already-completed' ? (
        <ErrorMessage>This todo is already completed.</ErrorMessage>
      ) : null}
      {completion === 'failed' ? <ErrorMessage>The todo could not be completed.</ErrorMessage> : null}
    </li>
  )
}
